import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.PlayStatus{Status: packet.PlayStatusPlayerSpawn}
PLAYER_SPAWN = bytes.fromhex("00000003")

# generated by gophertunnel b8bd735:
# packet.PlayStatus{Status: packet.PlayStatusLoginSuccess}
LOGIN_SUCCESS = bytes.fromhex("00000000")

# generated by gophertunnel b8bd735:
# packet.PlayStatus{Status: packet.PlayStatusLoginFailedVanillaEditor}
LOGIN_FAILED_VANILLA_TO_EDITOR = bytes.fromhex("00000009")

GOLDENS = [
    *[
        pytest.param(
            version.PlayStatusPacket(status=version.PlayStatus.PLAYER_SPAWN),
            PLAYER_SPAWN,
            id=f"{version.__name__.rpartition('.')[2]}-player-spawn",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.PlayStatusPacket(status=version.PlayStatus.LOGIN_SUCCESS),
            LOGIN_SUCCESS,
            id=f"{version.__name__.rpartition('.')[2]}-login-success",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.PlayStatusPacket(status=version.PlayStatus.LOGIN_FAILED_EDITOR_MISMATCH_VANILLA_TO_EDITOR),
            LOGIN_FAILED_VANILLA_TO_EDITOR,
            id=f"{version.__name__.rpartition('.')[2]}-login-failed-vanilla-to-editor",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_play_status_is_packet_2(version):
    assert version.PACKETS[2] is version.PlayStatusPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_play_status_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_play_status_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_play_status_rejects_a_truncated_status(version):
    with pytest.raises(ValueError, match="at byte"):
        version.PlayStatusPacket.from_bytes(PLAYER_SPAWN[1:])
